//go:build bdd

// Code generated by `true-bdd build tests`. DO NOT EDIT.
//
// Source: docs/scenarios.yaml
//
// One Go test per registry scenario, with the scenario's steps stated
// literally: what a reader sees here is what the machine runs. Done
// checks these steps against the registry before running any of them,
// so a hand edit to either side fails the test rather than quietly
// making the two documents disagree.
//
// Scenarios sharing a `path:` are written here in id order, so an
// inserted scenario lands where a reader expects it instead of at the
// end. Sequential by design — the suite's harness is shared.

package truebdd_test

import (
	"testing"
)

// build-steps-writing-010-scenario-run-fix: A suite Item adds the Scenario run without rewriting complete definitions or dispatching AI
func TestBuildStepsWriting010ScenarioRunFix(t *testing.T) {
	s := New(t, "build-steps-writing-010-scenario-run-fix")
	s.Given(`the "build-steps-scenario-run-fix" project tree`)
	s.And(`the System Architect's answer to every question is "1"`)
	s.When(`the System Architect runs "build steps --fix"`)
	s.Then(`the command exits with code 0`)
	s.And(`the engine dispatched no AI turns`)
	s.And(`stdout matches BUILD STEPS COMPLETE`)
	s.And(`the file "tests/calc/steps/state.go" matches \*testkit.ScenarioRun`)
	s.And(`the file "tests/calc/steps/state.go" matches Program string`)
	s.And(`the file "tests/calc/steps/state.go" matches Value\s+int`)
	s.And(`the file "tests/calc/steps/state.go" matches func \(state \*State\) Reset\(\)`)
	s.And(`the file "tests/calc/steps/register.go" is unchanged`)
	s.And(`no file outside "tmp" and "tests/calc/steps" changed`)
	s.Done()
}

// build-steps-writing-011-scenario-run-bare: A bare run reports a missing Scenario run by suite without changing definitions
func TestBuildStepsWriting011ScenarioRunBare(t *testing.T) {
	s := New(t, "build-steps-writing-011-scenario-run-bare")
	s.Given(`the "build-steps-scenario-run-bare" project tree`)
	s.When(`the System Architect runs "build steps"`)
	s.Then(`the command exits with code 1`)
	s.And(`the engine dispatched no AI turns`)
	s.And(`stderr matches tests/calc`)
	s.And(`stdout does not match BUILD STEPS COMPLETE`)
	s.And(`no file outside "tmp" changed`)
	s.Done()
}

// build-steps-writing-012-scenario-run-present: A suite Item with its Scenario run passes without changing files
func TestBuildStepsWriting012ScenarioRunPresent(t *testing.T) {
	s := New(t, "build-steps-writing-012-scenario-run-present")
	s.Given(`the "build-steps-scenario-run-present" project tree`)
	s.When(`the System Architect runs "build steps"`)
	s.Then(`the command exits with code 0`)
	s.And(`the engine dispatched no AI turns`)
	s.And(`stdout matches BUILD STEPS COMPLETE`)
	s.And(`no file outside "tmp" changed`)
	s.Done()
}
